using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
using OcctSharp.Generator.TypeMapping;
namespace OcctSharp.Generator.Tests;

public sealed class BulkCollectionContractTests
{
    static BindingType Type(string name,bool mutable=false)=>new(name,name,name,name,mutable?[new(BindingTypeLayerKind.LValueReference,false),new(BindingTypeLayerKind.Value,false)]:[new(BindingTypeLayerKind.Value,false)],null,[],false,null);
    static BindingDeclaration Hunt(){var op=BulkCollectionOperationContract.Operations.Values.Single(o=>o.NativeName=="BSplCLib::Hunt");return new(op.StableId,op.NativeName,BindingDeclarationKind.Method,"BSplCLib.hxx",0,0){NativeSignature=op.Signature,IsStatic=true,ProductModule=OcctProductModule.Foundation,Access=BindingAccess.Public,ReturnType=Type("void"),Parameters=[new(0,"knots",Type("NCollection_Array1<double>"),false),new(1,"value",Type("double"),false),new(2,"index",Type("int",true),false)]};}
    [Fact] public void ExactCatalogueIsClosedAndIncludesBothDimensions(){Assert.Equal(42,BulkCollectionOperationContract.Operations.Count);Assert.Equal(10,BulkCollectionOperationContract.Operations.Values.Count(o=>o.NativeName.StartsWith("Geom",StringComparison.Ordinal)));var d=Hunt();Assert.True(BulkCollectionOperationContract.Contains(d));Assert.False(BulkCollectionOperationContract.Contains(d with{NativeSignature="drift"}));Assert.False(BulkCollectionOperationContract.Contains(d with{Access=BindingAccess.Private}));}
    [Fact] public void ScalarReferencesRequireExactAdmission(){var d=Hunt();var t=Type("int",true);Assert.True(BulkCollectionOperationContract.TryMap(d,t,BindingTypeUsage.Parameter,new InitialTypeMap(),out var p));Assert.Equal("ValueCopy",p!.Ownership);Assert.False(BulkCollectionOperationContract.TryMap(d with{StableId="raw-buffer"},t,BindingTypeUsage.Parameter,new InitialTypeMap(),out _));}
    [Fact] public void BulkOutputChecksAndRefPublicationAreTransactional(){var files=CopiedCollectionOperationEmitter.Emit("8.0.1",new([Hunt()]),[],new HashSet<string>(),[],bulk:true).Files;Assert.Equal(3,files.Count);string cpp=files.Single(f=>f.RelativePath.EndsWith(".cpp",StringComparison.Ordinal)).Content;Assert.Contains("*updated2 = {};",cpp,StringComparison.Ordinal);Assert.Contains("Hunt midpoint overflows",cpp,StringComparison.Ordinal);Assert.Contains("Bulk array operation requires one-based bounds",cpp,StringComparison.Ordinal);string cs=files.Single(f=>f.RelativePath.EndsWith(".cs",StringComparison.Ordinal)).Content;Assert.True(cs.IndexOf("ThrowIfFailed",StringComparison.Ordinal)<cs.IndexOf("arg2 = updated2",StringComparison.Ordinal));}
    [Fact] public void CurveContainersDoNotOpenUnlistedTemplateMapping(){var d=Hunt() with{StableId="unlisted"};Assert.False(BulkCollectionOperationContract.TryMap(d,Type("NCollection_Array1<occ::handle<Geom_BSplineCurve>>"),BindingTypeUsage.Parameter,new InitialTypeMap(),out _));}
    [Fact] public void ConversionEmissionCopiesSingletonAndConcatInputs(){var op=BulkCollectionOperationContract.Operations.Values.Single(o=>o.NativeName=="GeomConvert::C0BSplineToArrayOfC1BSplineCurve"&&o.Signature.EndsWith("&, const double)",StringComparison.Ordinal));var d=new BindingDeclaration(op.StableId,op.NativeName,BindingDeclarationKind.Method,"GeomConvert.hxx",0,0){NativeSignature=op.Signature,Access=BindingAccess.Public,IsStatic=true,ProductModule=OcctProductModule.Geometry,ReturnType=Type("void"),Parameters=[new(0,"source",Type("curve"),false),new(1,"result",Type("set"),false),new(2,"tol",Type("double"),false)]};var files=CurveCollectionOperationEmitter.Emit("8.0.1",new([d]),[]).Files;string cpp=files.Single(f=>f.RelativePath.EndsWith(".cpp",StringComparison.Ordinal)).Content;Assert.Contains("CopyCurve(OcctSharpGenerated::ValidateGeomBSplineCurve(source)->Value)",cpp,StringComparison.Ordinal);Assert.Contains("Publication<CurveSet<Geom_BSplineCurve>> published(CopySet(output))",cpp,StringComparison.Ordinal);Assert.Contains("capacity>=static_cast<int>(value->indices.size())",cpp,StringComparison.Ordinal);string cs=files.Single(f=>f.RelativePath.EndsWith(".cs",StringComparison.Ordinal)).Content;Assert.Contains("DangerousAddRef",cs,StringComparison.Ordinal);Assert.Contains("DangerousRelease",cs,StringComparison.Ordinal);}
}
